// One item per calendar (an empty list still gives one, so Elliot's own
// address is found and saved).
let list = $input.first().json.calendars;
if (typeof list === 'string') { try { list = JSON.parse(list); } catch (e) { list = []; } }
list = Array.isArray(list) ? list : [];
return list.length ? list.map((c) => ({ json: c })) : [{ json: { kind: 'none', calendar_id: '' } }];

// What Elliot's Google account can do with each calendar (0042):
//   ok         -- can see free times and add viewings
//   read_only  -- shared, but only "See all event details" / free-busy
//   not_shared -- not shared with Elliot's account (or the address is wrong)
//   error      -- something else (Google's message is kept)
const list = $('Split Calendars').all().map((i) => i.json);
const added = $('Add To Elliot\'s Calendars').all().map((i) => i.json);
const fb = $('Check Free Times').first().json;
let fbBody = fb.body;
if (typeof fbBody === 'string') { try { fbBody = JSON.parse(fbBody); } catch (e) { fbBody = {}; } }
const cals = (fbBody && fbBody.calendars) || {};
const acct = $('Elliot\'s Google Account').first().json;
let acctBody = acct.body;
if (typeof acctBody === 'string') { try { acctBody = JSON.parse(acctBody); } catch (e) { acctBody = {}; } }
const results = list.filter((c) => c.calendar_id).map((c, i) => {
  const a = added[i] || {};
  let ab = a.body;
  if (typeof ab === 'string') { try { ab = JSON.parse(ab); } catch (e) { ab = {}; } }
  const st = Number(a.statusCode || 0);
  const role = (st >= 200 && st < 300 && ab && ab.accessRole) || '';
  const fbErr = cals[c.calendar_id] && cals[c.calendar_id].errors && cals[c.calendar_id].errors[0];
  let status, error = '';
  if (role === 'owner' || role === 'writer') status = 'ok';
  else if (role === 'reader' || role === 'freeBusyReader') status = 'read_only';
  else if (st === 404 || (fbErr && /notFound/i.test(fbErr.reason || ''))) status = 'not_shared';
  else if (st === 409 && !fbErr) status = 'ok';
  else {
    status = 'error';
    error = String((ab && ab.error && ab.error.message) || (fbErr && fbErr.reason) || `Google answered ${st || 'nothing'}`).slice(0, 300);
  }
  return { kind: c.kind, member_id: c.member_id || null, calendar_id: c.calendar_id, status, role, error };
});
return [{ json: { results, account_email: (acctBody && acctBody.id) || '' } }];
